export const DEFAULT_INCLUDE = ['**/*'];
export const DEFAULT_EXCLUDE = ['**/node_modules/**', '**/target/**', '**/bin/**', '**/obj/**', '**/.git/**', '**/dist/**', '**/build/**', '**/.idea/**', '**/.vs/**', '**/__pycache__/**', '**/.venv/**', '**/venv/**', '**/test-results/**', '**/playwright-report/**'];   // never read node_modules, target, bin, obj, dist, venv…

const MAX_BYTES = 2 * 1024 * 1024;
const CONFIG_NAMES = /^(pom\.xml|build\.gradle(?:\.kts)?|settings\.gradle(?:\.kts)?|requirements(?:-\w+)?\.txt|pyproject\.toml|setup\.cfg|pytest\.ini|tox\.ini|testng\.xml|package\.json|package-lock\.json|tsconfig\.json|wdio\.conf\.(?:js|ts)|cypress\.config\.(?:js|ts)|cypress\.json|\.babelrc|jest\.config\.(?:js|ts)|conftest\.py|nunit\.config|runsettings|.*\.runsettings|.*\.csproj|.*\.sln|Directory\.Build\.props|behave\.ini|cucumber\.properties|cucumber\.js|karate-config\.js)$/i;
const TEST_PLAN_NAME = /(test[-_ ]?(plan|cases?|matrix|suite|scenarios?)|regression|smoke|uat|acceptance)/i;   // a markdown file earns test-plan by name or by shape

  // …

/** Classify a single file from its relative path and content. Pure. */
export function classifyFile(rel: string, content: string): FileKind {
  const base = path.basename(rel);
  const ext = path.extname(rel).toLowerCase();
  if (ext === '.feature') return 'cucumber-feature';   // extension alone is enough here
  if (CONFIG_NAMES.test(base)) return 'config';
  switch (ext) {
    case '.java': return classifyJava(content);   // step-definitions → selenium-java → page-object → unknown
    case '.py': return classifyPython(content);
    case '.cs': return classifyCSharp(content);
    case '.js': case '.mjs': case '.cjs': case '.ts': case '.mts': case '.jsx': case '.tsx': return classifyJs(content);
    case '.json': return isPostmanCollection(content) ? 'postman-collection' : 'unknown';   // JSON must carry the getpostman schema URL
    case '.md': case '.docx': case '.xlsx': case '.txt': case '.csv':
      return TEST_PLAN_NAME.test(base) || (ext === '.md' && /^#+\s*.*\b(test|scenario|case)\b/im.test(content) && /^\s*(?:\d+[.)]|[-*])\s+/m.test(content)) ? 'test-plan' : 'unknown';   // or: a heading mentioning test/scenario/case plus a numbered list
    default: return 'unknown';
  }
}

/** Parse all classes of a Java/C# file. */
export function parseClasses(src: string, dialect: Dialect, file: string): ClassInfo[] {
  const clean = stripCComments(src);   // newlines preserved: line numbers stay honest
  const classes: ClassInfo[] = [];
  const classRe = /^[ \t]*(?:(?:public|private|protected|internal|static|final|abstract|sealed|partial)\s+)*class\s+([A-Za-z_]\w*)[^{]*\{/gm;
  let cm: RegExpExecArray | null;
  while ((cm = classRe.exec(clean))) {
    const open = clean.indexOf('{', cm.index);
    const close = matchBrace(clean, open);   // string-aware, so a "}" inside a literal does not end the class
    if (close === -1) continue;
    const bodyStart = open + 1;
    const body = clean.slice(bodyStart, close);
    const bodyLine = lineOf(clean, bodyStart);
    classes.push(parseClassBody(cm[1], lineOf(clean, cm.index), body, bodyLine, dialect, file));
    // nested classes are rare in test code; do not descend
    classRe.lastIndex = close;
  }
  return classes;
}

