/** Build a TestSuite for a Java/C# source file. `kind` decides test-class vs page-object vs step-definitions. */
export function buildSuite(src: string, dialect: Dialect, file: string, kind: TestSuite['kind']): TestSuite {
  const suite = emptySuite(file, dialect, kind);
  const classes = parseClasses(src, dialect, file);
  for (const c of classes) {
    suite.className ??= c.name;
    Object.assign(suite.constants, c.fields.constants);
    suite.locators.push(...c.fieldLocators);   // @FindBy and By fields, with their alias
    const stepDefs: StepDefinition[] = [];
    const pageMethods: PageMethod[] = [];
    for (const m of c.methods) {
      const { steps, urls } = methodSteps(m, c, dialect, file);
      suite.urls.push(...urls);
      for (const s of steps) if (s.locator && !suite.locators.includes(s.locator)) suite.locators.push(s.locator);
      const testAnn = m.annotations.find((a) => TEST_ANN.test(a));   // @Test, @ParameterizedTest, [Fact], [TestMethod]…
      const hookAnn = m.annotations.map((a) => a.replace(/\(.*$/, '')).find((a) => HOOK_ANN[a]);   // @BeforeMethod / [SetUp] → beforeEach, @BeforeClass → beforeAll
      const stepAnn = m.annotations.map((a) => STEP_ANN.exec(a)).find(Boolean);
      if (testAnn) {
        const t: TestCase = { name: m.name, line: m.line, steps };
        suite.tests.push(t);
      } else if (hookAnn) {
        suite.hooks.push({ kind: HOOK_ANN[hookAnn], name: m.name, steps, line: m.line });
      } else if (stepAnn) {
        const patternLit = stepAnn[2].trim();
        const pattern = /^["']/.test(patternLit) ? unescapeLiteral(patternLit.replace(/^@/, '')) : patternLit;
        stepDefs.push({ keyword: stepAnn[1], pattern, regex: cucumberToRegex(pattern), params: m.params, steps, line: m.line, source: file });   // {string} → "([^"]*)", {int} → (-?\d+)
      } else if (kind === 'page-object' || (m.isPublic && steps.length > 0)) {   // a public method with browser steps is a page method
        pageMethods.push({ name: m.name, params: m.params, steps, line: m.line });
      }
    }
    if (stepDefs.length) suite.stepDefinitions = [...(suite.stepDefinitions ?? []), ...stepDefs];
    if (kind === 'page-object') suite.pageObjects.push({ name: c.name, source: file, locators: c.fieldLocators, methods: pageMethods });
  }
  return suite;
}

export function normalize(text: string, dialect: Dialect, scope: Scope, file: string, line: number): Normalized {
  const strs: string[] = [];
  const locs: Locator[] = [];
  const vals: TypedValue[] = [];
  const S = (i: number) => `«S${i}»`;
  const L = (loc: Locator) => { locs.push(loc); return `«L${locs.length - 1}»`; };
  const E = (loc: Locator) => { locs.push(loc); return `«E${locs.length - 1}»`; };
  const ES = (loc: Locator) => { locs.push(loc); return `«ES${locs.length - 1}»`; };
  const V = (v: TypedValue) => { vals.push(v); return `«V${vals.length - 1}»`; };
  const lit = (tok: string) => { const m = /«S(\d+)»/.exec(tok); return m ? strs[Number(m[1])] : undefined; };
  const mk = (strategy: LocatorStrategy, value: string): Locator => ({ strategy, value, source: { file, line } });

  let n = text.trim().replace(/;+$/, '').trim();
  n = n.replace(/\bawait\s+/g, '').replace(/^return\s+/, 'return ');
  n = n.replace(/\b(?:this|self)\.(?=\w*[dD]river\b|browser\b)/g, '');
  n = n.replace(STRING_RE, (m) => { strs.push(unescapeLiteral(m)); return S(strs.length - 1); });   // strings first: nothing inside a literal can confuse later regexes
  // C# verbatim/interpolated prefixes
  n = n.replace(/[@$]«S/g, '«S');

  // By.xxx("...")  (java / csharp / js)
  n = n.replace(/\bBy\.(\w+)\s*\(\s*«S(\d+)»\s*\)/g, (m, strat: string, si: string) => {   // Java / C# / JS By.xxx("…") → «L»
    const s = normalizeStrategy(strat); return s ? L(mk(s, strs[Number(si)])) : m;
  });

  // …

  // python legacy: find_element_by_id("x")
  n = n.replace(/[\w.]*\bfind_elements?_by_(\w+)\s*\(\s*«S(\d+)»\s*\)/g, (m, strat: string, si: string) => {   // python legacy finders
    const s = normalizeStrategy(strat); if (!s) return m;
    return m.includes('find_elements_') ? ES(mk(s, strs[Number(si)])) : E(mk(s, strs[Number(si)]));
  });
  // WebdriverIO / jQuery-style and Cypress
  n = n.replace(/(?<![\w.])\$\$\(\s*«S(\d+)»\s*\)/g, (_, si: string) => ES(mk('css', strs[Number(si)])));
  n = n.replace(/(?<![\w.])\$\(\s*«S(\d+)»\s*\)/g, (_, si: string) => E(mk('css', strs[Number(si)])));
  n = n.replace(/\bcy\.get\(\s*«S(\d+)»\s*\)/g, (_, si: string) => E(mk('css', strs[Number(si)])));   // Cypress reads the same engine
  n = n.replace(/\bcy\.contains\(\s*«S(\d+)»\s*\)/g, (_, si: string) => E(mk('text', strs[Number(si)])));

  // variable substitution (strings are tokenised, so word-boundary replace is safe)
  const ident = (name: string) => new RegExp(String.raw`(?<![\w.«])(?:this\.|self\.|_?)?\b${escapeRe(name)}\b(?!\s*\()`, 'g');
  for (const [name, loc] of scope.byVars) n = n.replace(ident(name), () => L(loc));   // By variables and @FindBy fields substituted by name
  for (const [name, loc] of scope.elements) n = n.replace(ident(name), () => E(loc));
  for (const [name, v] of scope.values) n = n.replace(ident(name), () => V(v));

  // driver.findElement(«L0») -> «E0» ; findElements -> «ES0»
  n = n.replace(/[\w.]*\b(?:findElements|FindElements|find_elements)\s*\(\s*«L(\d+)»\s*\)/g, (_, li: string) => `«ES${li}»`);
  n = n.replace(/[\w.]*\b(?:findElement|FindElement|find_element)\s*\(\s*«L(\d+)»\s*\)/g, (_, li: string) => `«E${li}»`);   // driver.findElement(«L0») → «E0»
  // new Select(«E0») / SelectElement / Select(...)
  n = n.replace(/(?:new\s+)?\b(?:Select|SelectElement)\s*\(\s*«E(\d+)»\s*\)/g, (_, ei: string) => `«E${ei}»`);

  // …

  // typed values
  n = n.replace(/«E(\d+)»\.(?:getText\(\)|Text\b|text\b|innerText\b|getText\b)/g, (_, ei: string) => V({ type: 'text', locator: locs[Number(ei)] }));   // el.getText() → «V» of type text, carrying its locator
  n = n.replace(/«E(\d+)»\.(?:getAttribute|GetAttribute|get_attribute|getProperty|getValue)\(\s*(«S\d+»)?\s*\)/g, (_, ei: string, s?: string) => {
    const attr = s ? lit(s) ?? 'value' : 'value';
    return V(attr === 'value' ? { type: 'value', locator: locs[Number(ei)] } : { type: 'attribute', locator: locs[Number(ei)], attribute: attr });
  });
  n = n.replace(/«E(\d+)»\.(?:isDisplayed\(\)|Displayed\b|is_displayed\(\)|isDisplayed\b|isVisible\(\)|isExisting\(\))/g, (_, ei: string) => V({ type: 'visible', locator: locs[Number(ei)] }));
  n = n.replace(/«E(\d+)»\.(?:isEnabled\(\)|Enabled\b|is_enabled\(\)|isEnabled\b)/g, (_, ei: string) => V({ type: 'enabled', locator: locs[Number(ei)] }));
  n = n.replace(/«E(\d+)»\.(?:isSelected\(\)|Selected\b|is_selected\(\))/g, (_, ei: string) => V({ type: 'selected', locator: locs[Number(ei)] }));
  n = n.replace(/«ES(\d+)»\.(?:size\(\)|Count\b|length\b|Count\(\))/g, (_, ei: string) => V({ type: 'count', locator: locs[Number(ei)] }));
  n = n.replace(/\blen\(\s*«ES(\d+)»\s*\)/g, (_, ei: string) => V({ type: 'count', locator: locs[Number(ei)] }));
  n = n.replace(new RegExp(String.raw`${DRIVER}\.(?:getTitle\(\)|Title\b|title\b|getTitle\b)`, 'g'), () => V({ type: 'title' }));   // driver.getTitle() → «V» of type title
  n = n.replace(new RegExp(String.raw`${DRIVER}\.(?:getCurrentUrl\(\)|Url\b|current_url\b|getUrl\(\)|getCurrentUrl\b)`, 'g'), () => V({ type: 'url' }));
  n = n.replace(new RegExp(String.raw`${DRIVER}\.(?:getPageSource\(\)|PageSource\b|page_source\b)`, 'g'), () => V({ type: 'pageSource' }));

// -- assignments (declaration keywords are optional)
const assign = /^(?:(?:final|private|public|protected|internal|static|readonly|var|let|const|val|IWebElement|WebElement|By|Select|SelectElement|String|string|int|long|bool|boolean|List<\w+>|IList<\w+>|ReadOnlyCollection<\w+>)\s+)*([A-Za-z_]\w*)\s*=\s*(?!=)(.+)$/.exec(n);   // declaration keywords optional: Java, C#, JS and Python all match
if (assign) {
  const [, name, rhs] = assign;
  const r = rhs.trim();
  if (/^«E\d+»$/.test(r)) { scope.elements.set(name, locOf(r)!); return none; }   // WebElement x = findElement(…): bind, emit nothing
  if (/^«ES\d+»$/.test(r)) { scope.elements.set(name, locOf(r)!); return none; }
  if (/^«L\d+»$/.test(r)) { scope.byVars.set(name, locOf(r)!); return none; }
  if (/^«V\d+»$/.test(r)) { scope.values.set(name, valOf(r)!); return none; }
  const s = lit(r); if (s !== undefined) { scope.constants[name] = s; return none; }   // String BASE_URL = "…" feeds resolveConcat
  const obj = /^new\s+([A-Z]\w*)\s*\(|^([A-Z]\w*)\s*\(/.exec(r);
  if (obj) {
    const cls = obj[1] ?? obj[2];
    if (!/Driver$|^Builder$|^WebDriverWait$|^Actions$|^Select(?:Element)?$|^Duration$|^TimeSpan$/.test(cls)) scope.objects.set(name, cls);
    return none;
  }
  if (NOISE_RE.test(r) || /^new\s+\w*Wait/.test(r) || /^new\s+Actions/.test(r)) return none;
  // something else assigned: keep as unknown only if it touches the browser
  if (/«[EL]\d+»|driver|browser/.test(r)) return unknown();
  return none;
}

if (NOISE_RE.test(n) && !/«E\d+»\.(?:click|Click|sendKeys|send_keys|SendKeys)/.test(n)) return none;   // driver.quit(), maximize(), implicitlyWait(): dropped

// …

// -- waits
if ((m = /\b(?:Thread\.sleep|Thread\.Sleep|time\.sleep|sleep|cy\.wait|pause)\s*\(\s*(\d+(?:\.\d+)?)?/.exec(n)) && !/until|Until/.test(n)) {   // hard wait → NOTE + flakiness finding
  const num = m[1] ? Number(m[1]) : undefined;
  const ms = num === undefined ? undefined : dialect === 'python' || /time\.sleep/.test(n) ? Math.round(num * 1000) : Math.round(num);
  return { steps: [step('wait', { hard: true, value: ms === undefined ? undefined : String(ms) })] };
}
if (/\b(?:WebDriverWait|until|Until|wait|Wait|waitFor\w*|ExpectedConditions|EC\.)\b/.test(n)) {
  const loc = locOf(n);
  if (loc) {
    const hidden = /invisibility|Invisibility|not\(|stalenessOf|Staleness/.test(n);
    return { steps: [step('wait', { locator: loc, hard: false, value: hidden ? 'hidden' : 'visible' })] };   // explicit wait → locator.waitFor
  }
  return unknown();
}

// …

// -- assertions
const a = parseAssertion(n, dialect, lit, valOf, locOf, strs, scope);   // TestNG, JUnit, NUnit, pytest, chai, node assert, cypress
if (a === 'unknown') return unknown();   // everything else: a TODO with the original line
if (a) return { steps: [step('assert', { assertion: a, locator: a.locator })] };

// -- return of a typed value (page object getters)
if ((m = /^return\s+«V(\d+)»$/.exec(n))) {
  const v = vals[Number(m[1])];
  return { steps: [step('read', { locator: v.locator, value: v.type, valueExpr: v.attribute })] };
}

// -- page-object method call
if ((m = /^(?:this\.|self\.)?([A-Za-z_]\w*)\.([A-Za-z_]\w*)\((.*)\)$/.exec(n)) && scope.objects.has(m[1])) {   // loginPage.login(QA_USER, QA_PASS) → call step
  const args = splitTopLevel(m[3]).map((arg) => {
    const r = resolveConcat(arg, strs, scope);
    return r.resolved ? JSON.stringify(r.value) : r.expr;
  });
  return { steps: [step('call', { call: { object: scope.objects.get(m[1])!, method: m[2], args } })] };
}

// Bare `«E0»` like a lone findElement (Java `driver.findElement(...).isDisplayed();` w/o assert) -> treat as visibility wait
if (/^«V\d+»$/.test(n)) {
  const v = valOf(n)!;
  if (v.type === 'visible' && v.locator) return { steps: [step('wait', { locator: v.locator, value: 'visible' })] };
}

if (!n) return none;
return unknown();

export function standardize(loc: Locator, opts: StdOptions = {}): StdLocator {
  const v = loc.value.trim();
  const base = (expr: string, confidence: number, note?: string): StdLocator => ({ expr, confidence, strategy: loc.strategy, note });
  switch (loc.strategy) {
    case 'id':
      if (opts.testIdAttribute === 'id' && looksLikeTestId(v)) return base(`page.getByTestId(${q(v)})`, 0.95);   // ids named like test ids become getByTestId
      if (/\s/.test(v) || !v) return base(`page.locator(${q(cssId(v))})`, 0.3, 'id contains whitespace or is empty');
      if (/\d{3,}/.test(v) || /^(?::|j_id|gwt-uid|ext-|yui_|ember\d|react-select-\d)/.test(v)) return base(`page.locator(${q(cssId(v))})`, 0.5, 'id looks auto-generated');   // gwt-uid, ember12, react-select-3, 3+ digit runs
      return base(`page.locator(${q(cssId(v))})`, 0.95);
    case 'testId':
      return base(`page.getByTestId(${q(v)})`, 0.95);
    case 'name':
      return base(`page.locator(${q(cssAttr('name', v))})`, 0.85);
    case 'linkText':   // link text is an accessible name: role locator, 0.9
      return base(`page.getByRole('link', { name: ${q(v)}, exact: true })`, 0.9);
    case 'partialLinkText':
      return base(`page.getByRole('link', { name: /${escapeRegex(v)}/ })`, 0.8);
    case 'className': {
      const classes = v.split(/\s+/).filter(Boolean);
      if (!classes.length) return base(`page.locator('.undefined')`, 0.1, 'empty class name');
      const sel = classes.map((c) => `.${c}`).join('');
      const utility = classes.some((c) => /^(?:col|row|btn|mt|mb|p|m|px|py|text|d|w|h|flex|grid|bg)-/.test(c));
      return base(`page.locator(${q(sel)})`, utility ? 0.5 : 0.65, utility ? 'utility/layout class names are not stable' : undefined);   // col-, btn-, mt-… are not stable
    }
    case 'tagName':
      return base(`page.locator(${q(v)})`, 0.5, 'tag name alone is ambiguous');
    case 'text':
      return base(`page.getByText(${q(v)})`, 0.85);
    case 'css': {
      const v = normalizeCssQuotes(loc.value.trim());
      const dt = /^\[(data-testid|data-test|data-qa|data-cy)=["']?([^"'\]]+)["']?\]$/.exec(v);
      if (dt && (!opts.testIdAttribute || opts.testIdAttribute === dt[1])) return base(`page.getByTestId(${q(dt[2])})`, 0.95);
      if (/:nth-child\(|:nth-of-type\(|>\s*\w+\s*>\s*\w+\s*>/.test(v)) return base(`page.locator(${q(v)})`, 0.5, 'positional/deeply chained css');   // :nth-child and > a > b > c chains
      if (/\d{3,}/.test(v)) return base(`page.locator(${q(v)})`, 0.55, 'css contains generated-looking numbers');
      return base(`page.locator(${q(v)})`, 0.8);
    }
    case 'xpath':
      return standardizeXpath(v, base);
  }
}

  // …

function standardizeXpath(xp: string, base: BaseFn): StdLocator {
  const s = xp.trim();
  if (/^\/html\b|^\/body\b/.test(s) || /^\/[^/]/.test(s)) return base(`page.locator(${q(`xpath=${s}`)})`, 0.2, 'absolute xpath is brittle');   // /html/body/… stays xpath= at 0.20

  // text() forms on a single segment
  let m: RegExpExecArray | null;
  if ((m = /^\/\/([a-zA-Z][\w-]*|\*)\[(?:normalize-space\(\)|text\(\)|\.)\s*=\s*(['"])(.*?)\2\]$/.exec(s))) {
    const role = ROLE_TAGS[m[1]];   // //a[text()=…] → getByRole('link'), //button → getByRole('button')
    if (role) return base(`page.getByRole(${q(role)}, { name: ${q(m[3])}, exact: true })`, 0.85);
    return base(`page.getByText(${q(m[3])}, { exact: true })`, 0.8);   // //p[text()=…] → getByText exact
  }
  if ((m = /^\/\/([a-zA-Z][\w-]*|\*)\[contains\((?:text\(\)|\.|normalize-space\(\))\s*,\s*(['"])(.*?)\2\)\]$/.exec(s))) {
    const role = ROLE_TAGS[m[1]];
    if (role) return base(`page.getByRole(${q(role)}, { name: /${escapeRegex(m[3])}/ })`, 0.8);
    return base(`page.getByText(${q(m[3])})`, 0.75);
  }

export function buildPlan(suites: TestSuite[]): Plan {
  const all = suites.flatMap((s) => s.locators);
  const stdOptions: StdOptions = { testIdAttribute: chooseTestIdAttribute(all) };   // decided once, from the whole estate
  const stdCache = new Map<string, StdLocator>();
  const std = (l: Locator) => { const k = locatorKey(l); let v = stdCache.get(k); if (!v) { v = standardize(l, stdOptions); stdCache.set(k, v); } return v; };
  const pages: PlannedPage[] = [];
  const pageByClass = new Map<string, PlannedPage>();
  const pageForSuite = new Map<string, PlannedPage>();
  const usedClassNames = new Set<string>();
  const usedFiles = new Set<string>();

  const uniqueClass = (base: string) => { let n = base; let i = 2; while (usedClassNames.has(n)) n = `${base}${i++}`; usedClassNames.add(n); return n; };   // two LoginPage classes → LoginPage, LoginPage2
  const fileFor = (className: string) => {
    let base = className.replace(/Page$/, '') || className;
    let f = `src/pages/${base}.page.ts`; let i = 2;
    while (usedFiles.has(f)) f = `src/pages/${base}${i++}.page.ts`;
    usedFiles.add(f); return f;
  };
  const makeFields = (locators: Locator[]): PlannedField[] => {
    const fields: PlannedField[] = [];
    const seen = new Map<string, PlannedField>();
    const names = new Set<string>();
    for (const l of locators) {
      const k = locatorKey(l);
      if (seen.has(k)) continue;
      const s = std(l);
      let name = fieldNameFor(l, s);
      if (/^(page|constructor|goto)$/.test(name)) name = `${name}Element`;   // never shadow the Page itself
      let n = name; let i = 2; while (names.has(n)) n = `${name}${i++}`;
      names.add(n);
      const f = { name: n, locator: l, std: s };
      seen.set(k, f); fields.push(f);
    }
    return fields;
  };

  // 1. detected page objects   // LoginPage.java → Login.page.ts
  for (const s of suites) for (const po of s.pageObjects) {
    const className = uniqueClass(po.name);
    // include locators used inline inside page methods too
    const inline = po.methods.flatMap((m) => m.steps.map((st) => st.locator).filter((x): x is Locator => !!x));
    const p: PlannedPage = { className, file: fileFor(className), fixture: lowerFirst(className), fields: makeFields([...po.locators, ...inline]), methods: po.methods, sourceFile: s.source, synthetic: false };
    pages.push(p); pageByClass.set(po.name, p);
  }
  // 2. one synthetic page per UI test suite / step-definition file that has inline locators   // CheckoutTest.java → Checkout.page.ts from its inline locators
  for (const s of suites) {
    if (!(isUiSuite(s) || s.kind === 'step-definitions')) continue;
    const inline = s.locators.filter((l) => !l.alias);
    if (!inline.length) continue;
    const raw = (s.className ?? s.source.replace(/^.*\//, '').replace(/\..*$/, '')).replace(/[^A-Za-z0-9]+/g, ' ').trim().split(' ').map(upperFirst).join('');
    const base = raw.replace(/^Test(?=[A-Z])/, '').replace(/(Tests?|Specs?|IT|Steps?|StepDefs?|StepDefinitions|Page)$/, '');   // CheckoutTest → CheckoutPage, LoginSteps → LoginStepsPage
    const preferred = `${base || 'Legacy'}Page`;
    const className = usedClassNames.has(preferred) ? uniqueClass(`${raw.replace(/Page$/, '')}Page`) : uniqueClass(preferred);
    const p: PlannedPage = { className, file: fileFor(className), fixture: lowerFirst(className), fields: makeFields(inline), methods: [], sourceFile: s.source, synthetic: true };
    pages.push(p); pageForSuite.set(s.source, p);
  }
  return { pages, pageForSuite, pageByClass, stdOptions, stdCache };
}

