export type ConversionStatus = 'converted' | 'partial' | 'manual';

/** Classify a body from its emitted steps: no TODOs -> converted; >=50% TODO (or all) -> manual; else partial. */
export function statusOf(total: number, todos: number): ConversionStatus {
  if (total === 0) return 'manual';
  if (todos === 0) return 'converted';
  if (todos * 2 >= total) return 'manual';   // half or more TODO → manual → test.fixme
  return 'partial';
}

export function generateEstate(suites: TestSuite[], opts: GenerateOptions): GenerateOutput {
  const baseUrl = opts.baseUrl ?? detectBaseUrl(suites);   // most common navigated origin, api.* hosts excluded
  const plan = buildPlan(suites);
  const files = new Map<string, string>();
  const fileStatuses: FileStatus[] = [];
  const todos: TodoItem[] = [];
  const flaky: GenerateOutput['flaky'] = [];
  const noAssertion: GenerateOutput['noAssertion'] = [];
  const totals = { tests: 0, converted: 0, partial: 0, manual: 0, steps: 0, stepsConverted: 0, coveragePct: 0 };
  const tally = (statuses: { status: ConversionStatus; total: number; todos: number }[]) => {   // per-file status and the global 99/108 step count
    const c = { converted: 0, partial: 0, manual: 0 };
    for (const s of statuses) { c[s.status]++; totals.steps += s.total; totals.stepsConverted += s.total - s.todos; }
    totals.tests += statuses.length; totals.converted += c.converted; totals.partial += c.partial; totals.manual += c.manual;
    return c;
  };
  const overall = (c: { converted: number; partial: number; manual: number }, n: number): FileStatus['status'] => n === 0 ? 'n/a' : c.converted === n ? 'converted' : c.manual === n ? 'manual' : 'partial';

  // page objects (detected + synthetic)
  for (const p of plan.pages) {
    const r = genPageClass(p, plan, baseUrl);   // detected and synthetic pages alike
    files.set(p.file, r.code);
    todos.push(...r.todos); flaky.push(...r.flaky);
    if (!p.synthetic) {
      const c = tally(r.statuses);
      fileStatuses.push({ source: p.sourceFile, kind: 'page-object', output: p.file, status: overall(c, r.statuses.length), tests: r.statuses.length, ...c });
    }
  }
  if (plan.pages.length) files.set('src/fixtures/index.ts', genFixtures(plan.pages));   // one fixture per page class

  // …

  // cucumber
  const featureSuites = suites.filter((s) => s.kind === 'cucumber-feature');
  const defSuites = suites.filter((s) => s.stepDefinitions?.length);
  for (const f of featureSuites) {
    const base = featureBaseName(f);
    files.set(`tests/features/${base}.feature`, f.feature ? reconstructFeature(f) : '');   // the .feature is kept, only the steps are regenerated
    const r = genStepDefinitions(f, defSuites, plan, baseUrl);
    files.set(`tests/steps/${base}.steps.ts`, r.code);
    todos.push(...r.todos); flaky.push(...r.flaky);
    const c = tally(r.scenarios);
    fileStatuses.push({ source: f.source, kind: 'cucumber-feature', output: `tests/features/${base}.feature + tests/steps/${base}.steps.ts`, status: overall(c, r.scenarios.length), tests: r.scenarios.length, ...c });
  }
  for (const d of defSuites) fileStatuses.push({ source: d.source, kind: 'step-definitions', output: featureSuites.length ? 'tests/steps/*.steps.ts' : '(no feature file references these definitions)', status: 'kept', tests: d.stepDefinitions!.length, converted: 0, partial: 0, manual: 0 });   // step-definition files are consumed, not converted

  // …

  const db = ctx.db;
  for (const l of gen.lowLocators) db.addFinding({ run_id: ctx.runId, severity: l.confidence < 0.4 ? 'high' : 'medium', category: 'locator', title: `Brittle locator (${l.strategy}): ${l.value.slice(0, 80)}`, detail: `${l.note ?? 'low confidence'} -> generated ${l.expr}`, evidence: { file: l.file, line: l.line, confidence: l.confidence } });   // absolute xpath at 0.20 → high
  for (const t of gen.todos) db.addFinding({ run_id: ctx.runId, severity: 'medium', category: 'conversion', title: `Unconvertible: ${t.raw.slice(0, 80)}`, detail: `in ${t.where}`, evidence: { file: t.file, line: t.line } });   // one per TODO
  for (const f of gen.flaky) db.addFinding({ run_id: ctx.runId, severity: 'low', category: 'flakiness', title: `Hard wait removed: ${f.raw.slice(0, 80)}`, detail: 'Playwright auto-waits; the sleep was replaced with a NOTE comment.', evidence: { file: f.file, line: f.line } });   // one per removed sleep
  for (const d of gen.duplicates.slice(0, 50)) db.addFinding({ run_id: ctx.runId, severity: 'low', category: 'duplication', title: `Locator duplicated in ${d.files.length} files: ${d.strategy}=${d.value.slice(0, 60)}`, detail: d.files.join(', '), evidence: d });
  for (const n of gen.noAssertion) db.addFinding({ run_id: ctx.runId, severity: 'low', category: 'quality', title: `Test without assertion: ${n.test}`, evidence: { file: n.file } });   // a passing test that asserts nothing proves nothing

