export class LoginPage {
  readonly usernameInput: Locator;
  readonly passwordInput: Locator;
  readonly signInButton: Locator;
  readonly errorBanner: Locator;
  readonly forgotPasswordLink: Locator;

  constructor(readonly page: Page) {
    this.usernameInput = page.locator('#username');                                   // id → 0.95
    this.passwordInput = page.locator('[name="password"]');                            // name → 0.85
    this.signInButton = page.locator('button[type="submit"]');                         // css, quotes normalised → 0.80
    this.errorBanner = page.locator('div[class="alert alert-danger"]');                // xpath reduced; exact multi-class → 0.60, on the line, not flagged
    this.forgotPasswordLink = page.getByRole('link', { name: 'Forgot your password?', exact: true });   // linkText → 0.90
  }

  async open(): Promise<void> { await this.page.goto('/login'); }

  async login(user: string, pass: string): Promise<void> {
    await this.usernameInput.clear();
    await this.usernameInput.fill(user);
    await this.passwordInput.fill(pass);
    await this.signInButton.click();
  }

  async errorText(): Promise<string> {
    return (await this.errorBanner.textContent()) ?? '';
  }

  async goToForgotPassword(): Promise<void> { await this.forgotPasswordLink.click(); }
}

Field names are the Java aliases, kept. Method parameters (user, pass) stayed parameters because the emitter saw them in the method's param set. The return type Promise<string> was derived from the trailing read step. PageFactory.initElements and the WebDriver field were dropped as noise.
